// Turkish texts of catalog.mjs: [English text, Turkish text], in catalog order. The English side must match the T() text
// exactly (the build names any text without a translation and any entry whose English text changed or went away).
// Terms follow the app (src/Filee.App/Assets/i18n/tr.json): ön ayar (preset), motor / dönüştürme motoru (engine),
// isteğe bağlı motor (optional engine), halka / halka araç çubuğu (donut, donut toolbar), dilim (slice), izlenen klasörler
// (watch folders), bırakma alanı (drop zone), biçim (format), Ayarlar → Dönüştürme motorları (Settings → Engines),
// “Filee ile dönüştür” (Convert with Filee), preset names as in the app (PDF birleştir, PDF sıkıştır, SVG'ye
// vektörleştir…). The plain category names are singular so that they read as modifiers ("Tüm görsel biçimleri").
// Suffixes never follow a placeholder: Turkish suffixes depend on how a format name is pronounced.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`, `video ve ses, altyazı çıkarma ve HEIC olarak kaydetme`],
  [`older office formats such as DOC, PPT and ODT`, `DOC, PPT ve ODT gibi eski ofis biçimleri`],
  [`rare e-book formats and MOBI/AZW3 output`, `nadir e-kitap biçimleri ve MOBI/AZW3 çıktısı`],
  [`EPS and PostScript`, `EPS ve PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc ve diğer işaretleme dilleri, Word → Markdown ve Markdown → slaytlar`],

  // Options
  [`quality`, `kalite`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `JPG, WEBP ve AVIF için ayarlanabilir kalite: JPG varsayılan olarak %90 kaliteyle kaydedilir, JPG 70% ön ayarı ise daha küçük dosyalar oluşturur.`],
  [`resize`, `yeniden boyutlandırma`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Dönüştürürken yüzdeyle (örneğin yarı boyut) veya uzun kenar için bir üst sınırla yeniden boyutlandırma.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Görsele yazılan DPI değerini ayarlayın, örneğin baskı için 300.`],
  [`grayscale`, `gri tonlama`],
  [`A grayscale preset makes black-and-white copies.`, `Gri tonlama ön ayarı siyah beyaz kopyalar oluşturur.`],
  [`metadata`, `üst veri`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Üst veri (EXIF, XMP, renk profili) varsayılan olarak korunur ve gizlilik için kaldırılabilir.`],
  [`ICO sizes`, `ICO boyutları`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `ICO dosyaları varsayılan olarak 256, 128, 64, 48, 32 ve 16 px boyutlarını içerir; boyutlar ön ayarda değiştirilebilir.`],
  [`TIFF compression`, `TIFF sıkıştırması`],
  [`TIFF compression can be chosen (LZW by default).`, `TIFF sıkıştırması seçilebilir (varsayılan LZW).`],
  [`white background`, `beyaz arka plan`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG saydamlığı desteklemediği için saydam alanlar beyazla doldurulur.`],
  [`merge into one PDF`, `tek PDF'de birleştirme`],
  [`The merge preset combines all dropped files into one PDF.`,
    `PDF birleştir ön ayarı bırakılan tüm dosyaları tek bir PDF'de birleştirir.`],
  [`split pages`, `sayfalara bölme`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `PDF böl ön ayarı her sayfayı bir alt klasöre ayrı bir PDF olarak kaydeder.`],
  [`rotate & flip`, `döndürme ve çevirme`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Döndür ve Çevir ön ayarları görselleri, fotoğrafın kendi yönü uygulandıktan sonra sola, sağa veya 180° döndürür ve aynalar.`],
  [`Trace to SVG`, `SVG'ye vektörleştirme`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `İki ön ayar bir görseli vektörel şekillere dönüştürür: SVG'ye vektörleştir en fazla 64 renkle, Çizgileri SVG'ye dönüştür ise logolar, imzalar ve taramalar için siyahla. Başka bir program gerekmez.`],
  [`remove background`, `arka plan kaldırma`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Arka planı kaldır ön ayarı düz bir arka planı saydamlaştırır: imza veya kaşenin arkasındaki kâğıt, bir logonun arka planı.`],
  [`page ranges`, `sayfa aralıkları`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `1-3,5 gibi sayfa aralıkları dönüştürmeyi ihtiyacınız olan sayfalarla sınırlar.`],
  [`render DPI`, `işleme DPI'ı`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Sayfalar varsayılan olarak 150 DPI ile işlenir; baskı kalitesi için 300 DPI seçin.`],
  [`one long image`, `tek uzun görsel`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Uzun görsel ön ayarı tüm sayfaları tek bir uzun görselde alt alta dizer; örneğin bir belgenin tamamını tek seferde paylaşmak için.`],
  [`compress PDF`, `PDF sıkıştırma`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `PDF sıkıştır ön ayarı PDF'yi PDF olarak bırakarak küçültür: görseller 72, 150 veya 300 dpi'ye küçültülür ve fotoğraflar yeniden JPEG olarak kaydedilir; metin, yazı tipleri, bağlantılar, yer imleri ve formlar olduğu gibi kalır. Küçültülemeyen bir PDF olduğu gibi bırakılır. Ghostscript kuruluysa Filee onu da dener ve daha küçük sonucu tutar.`],
  [`a picture per slide`, `slayt başına bir görsel`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (slaytlar) her sayfanın görselini sayfa boyutunda ayrı bir slayta yerleştirir; sayfanın metni konuşmacı notlarına eklenir. Slaytlar PDF'nin birebir aynısı gibi görünür ancak düzenlenemez; düzenlenebilir metin için DOCX'e dönüştürün.`],
  [`vector PDF`, `vektörel PDF`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `PDF vektörel kalır; her yakınlaştırmada ve baskıda net görünür.`],
  [`editable`, `düzenlenebilir`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Sonuç, sayfa görselleri değil, düzenleyebileceğiniz gerçek metin ve paragraflar içerir.`],
  [`attachments as ZIP`, `ekler ZIP olarak`],
  [`Attachments can be saved separately as one ZIP.`, `Ekler ayrıca tek bir ZIP olarak kaydedilebilir.`],
  [`one CSV per sheet`, `çalışma sayfası başına bir CSV`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Birden fazla çalışma sayfası olan çalışma kitapları her sayfa için bir CSV verir.`],
  [`layout kept`, `düzen korunur`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Sayfa boyutu ve kenar boşluklarını, sayfa numaralı üst ve alt bilgileri, tabloları, metin kutularını, şekilleri ve görselleri korur.`],
  [`no Office needed`, `Office gerekmez`],
  [`No Microsoft Office or LibreOffice needed.`, `Microsoft Office veya LibreOffice gerekmez.`],
  [`no Hancom Office needed`, `Hancom Office gerekmez`],
  [`No Hancom Office and no approval dialog.`, `Hancom Office de izin penceresi de gerekmez.`],
  [`no AutoCAD needed`, `AutoCAD gerekmez`],
  [`No AutoCAD or DWG viewer needed.`, `AutoCAD veya DWG görüntüleyici gerekmez.`],
  [`no re-encoding`, `yeniden kodlama yok`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Yeni biçim videoyu ve sesi olduğu gibi tutabiliyorsa (iPhone MOV → MP4) yalnızca kapsayıcıları değiştirilir: kalite kaybı olmaz, HDR korunur, işlem saniyeler sürer.`],
  [`720p option`, `720p seçeneği`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `MP4 720p ön ayarı büyük videoları paylaşım için küçültür.`],
  [`extract audio`, `ses çıkarma`],
  [`Only the sound is saved, without the video track.`, `Video izi olmadan yalnızca ses kaydedilir.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `MP3 128k ön ayarı daha küçük dosyalar oluşturur; konuşma kayıtları için idealdir.`],
  [`extract`, `arşivi açma`],
  [`The extract preset unpacks an archive into a folder instead.`, `Arşivi aç ön ayarı ise arşivi bir klasöre açar.`],
  [`pack into one ZIP`, `tek ZIP'e paketleme`],
  [`Any selection of files can be packed into one ZIP.`, `Seçtiğiniz her dosya grubu tek bir ZIP'e paketlenebilir.`],
  [`DRM-free books`, `DRM'siz kitaplar`],
  [`Works with DRM-free books only.`, `Yalnızca DRM'siz kitaplarla çalışır.`],
  [`ALAC in M4A`, `M4A içinde ALAC`],
  [`M4A can hold lossless ALAC as well as AAC.`, `M4A, AAC'nin yanı sıra kayıpsız ALAC da tutabilir.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Video ön ayarları daha küçük dosyalar için HEVC (H.265) veya AV1 ile kodlayabilir; 10 bit ve HDR video korunur.`],
  [`hardware encoding`, `donanım kodlama`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `H.264 ve HEVC'yi grafik işlemcisinde (NVENC, Quick Sync, AMF, VideoToolbox veya VA-API) kodlamak için bir video ön ayarında “Donanım hızlandırması kullan” seçeneğini açın: çok daha hızlıdır ve daha az güç tüketir, aynı kalitede dosya biraz daha büyük olur. Varsayılan olarak kapalıdır; uygun bir işlemci yoksa video eskisi gibi kodlanır.`],
  [`every frame`, `her kare`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Bir video normalde tek bir durağan kare verir. Kareleri çıkar ön ayarları ya da bir PNG veya JPG ön ayarındaki “Videonun her karesini kaydet” seçeneği her kareyi (veya her N'inci kareyi) videonun yanındaki bir klasöre görsel olarak kaydeder.`],
  [`extract subtitles`, `altyazı çıkarma`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Video halkasındaki Altyazıları çıkar ön ayarı, videonun ilk metin altyazı izini SRT olarak kaydeder.`],
  [`saved as UTF-8`, `UTF-8 olarak kaydedilir`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Sonuçlar UTF-8 olarak kaydedilir. CP949 (EUC-KR) ile kaydedilmiş Korece dosyalar algılanır ve doğru okunur.`],
  [`tables to CSV / Excel`, `tablolar CSV / Excel'e`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Tablo biçimindeki veriler (kayıt listeleri) CSV ve Excel'e, CSV ve Excel'den de dönüştürülür.`],
  [`picture preview`, `görsel önizleme`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG veya JPG, modelin sağ önden ve yukarıdan görülen gölgelendirilmiş bir görselini verir.`],
  [`colours and textures`, `renkler ve dokular`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Renkler, dokular ve malzemeler, hedef biçim destekliyorsa korunur. STL yalnızca şekli tutar.`],
  [`HDR tone-mapped`, `HDR ton eşleme`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Windows'un JPEG XR olarak kaydettiği HDR ekran görüntüleri kırpılmak yerine ton eşlemesiyle normal parlaklığa getirilir.`],
  [`Live Photo video`, `Live Photo videosu`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Live Photo videosunu çıkar ön ayarı, bir iPhone Live Photo'nun (iCloud'dan gelen bir LIVP ya da MOV dosyası yanında duran bir fotoğraf) veya bir Android Motion Photo'nun videosunu MP4 ya da MOV olarak kaydeder. Tersine, Live Photo (iPhone) ve Motion Photo (Android) ön ayarları bir videodan alınan kısa bir klibi hareketli fotoğrafa dönüştürür; bu özellik hâlâ deneyseldir.`],
  [`WGS 84 longitude / latitude`, `WGS 84 boylam / enlem`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Sonuçlar her zaman boylam ve enlem (WGS 84) cinsindendir. UTM, Web Mercator, Lambert veya Albers projeksiyonlu Shapefile'lar dönüştürülür ve doğru yerde açılır; bir dosyayı kendi biçimine dönüştürdüğünüzde koordinatları WGS 84'e çevrilir.`],
  [`save as ZIP`, `ZIP olarak kaydetme`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Bir Shapefile beş dosyadan oluşur (.shp, .shx, .dbf, .prj ve .cpg). Bir ön ayardaki “Sonucu ZIP olarak kaydet” seçeneğiyle ya da ayarlarda tüm coğrafi veri sonuçları için bu seçenek açıkken hepsi tek bir ZIP içinde birlikte taşınır.`],
  [`Canon CR2 RAW photo`, `Canon CR2 RAW fotoğrafı`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2, Canon DSLR fotoğraf makinelerinin uzun yıllar kullandığı RAW fotoğraf biçimidir (yeni Canon modelleri CR3 yazar). İşlenmemiş sensör verisini sakladığı için düzenlemede geniş bir alan bırakır.`],
  [`Nikon NEF RAW photo`, `Nikon NEF RAW fotoğrafı`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF, Nikon DSLR ve Z aynasız fotoğraf makinelerinin kullandığı Nikon RAW fotoğraf biçimidir. Diğer RAW dosyaları gibi işlenmemiş sensör verisi içerir ve bir JPG'den birkaç kat büyüktür.`],

  // Text that needs shaping
  [`DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX with text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) go to PDF and images through the optional LibreOffice engine`,
    `Şekillendirme gerektiren metin (Arapça, İbranice, Hint yazıları, Tayca ve diğerleri) içeren DOCX, TXT, Markdown, HTML, XLSX, PPTX ve HWPX dosyaları isteğe bağlı LibreOffice motoruyla PDF'ye ve görsellere dönüştürülür`],
  [`Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Şekillendirme gerektiren metin (Arapça, İbranice, Hint yazıları, Tayca ve diğerleri) bir istisnadır: böyle metin içeren DOCX, TXT, Markdown, HTML, XLSX, PPTX ve HWPX dosyaları isteğe bağlı LibreOffice motoruyla PDF'ye ve görsellere dönüştürülür. LibreOffice yoksa dosya, bozuk bir PDF'ye dönüşmek yerine yazı sisteminin adını belirten bir mesajla başarısız olur.`],

  // Images
  [`Images`, `Görseller`],
  [`images`, `görsel`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `iPhone HEIC ve Live Photo'lar, Photoshop PSD, tüm büyük markaların kamera RAW dosyaları, animasyonlu APNG, DICOM ve Windows'un HDR ekran görüntüleri (JPEG XR) dahil fotoğraflar ve grafikler. Dönüştürürken yeniden boyutlandırın, döndürün, kalite ve DPI ayarlayın, üst veriyi kaldırın ya da bir görseli SVG'ye vektörleştirin.`],
  [`JPEG image`, `JPEG görseli`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG en yaygın fotoğraf biçimidir. Kayıplı sıkıştırması dosyaları küçük tutar, ancak düşük kalitede yapılan her kayıt biraz ayrıntı kaybettirir; saydamlık desteği de yoktur.`],
  [`PNG image`, `PNG görseli`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG, saydamlığı destekleyen kayıpsız bir görsel biçimidir; ekran görüntüleri, logolar ve keskin kenarlı grafikler için idealdir. PNG olarak kaydedilen fotoğraflar genellikle JPG'den çok daha büyüktür.`],
  [`WebP image`, `WebP görseli`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP, Google'ın web için geliştirdiği görsel biçimidir. Kayıplı ve kayıpsız sıkıştırmayı ve saydamlığı destekler, genellikle JPG veya PNG'den küçüktür; ancak bazı düzenleyiciler ve yükleme formları onu hâlâ kabul etmez.`],
  [`AVIF image`, `AVIF görseli`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF, AV1 video codec'ine dayanan modern bir görsel biçimidir. JPG ve WebP'den daha iyi sıkıştırır, ancak eski yazılım ve cihazlarda desteği hâlâ sınırlıdır.`],
  [`HEIC / HEIF image`, `HEIC / HEIF görseli`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF), iPhone ve iPad'lerin varsayılan olarak kullandığı fotoğraf biçimidir. Fotoğraflar çoğu zaman bir JPG'nin yarısı kadar yer kaplar, ancak birçok Windows uygulaması, web sitesi ve eski cihaz bunları açamaz.`],
  [`GIF image / animation`, `GIF görseli / animasyonu`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF, 256 renkle sınırlı, basit animasyonları destekleyen eski bir görsel biçimidir. Sohbetlerde, belgelerde ve hata raporlarında kısa, sessiz döngüler paylaşmanın hâlâ evrensel yoludur.`],
  [`Windows icon`, `Windows simgesi`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO, Windows simge biçimidir. Tek bir ICO dosyası aynı görseli birkaç boyutta (örneğin 16, 32, 48 ve 256 piksel) tutar; böylece görev çubuğundan web sitesi favicon'larına kadar her yerde net görünür.`],
  [`Photoshop document`, `Photoshop belgesi`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD, Adobe Photoshop'un kendi biçimidir. Katmanları, maskeleri ve ayar katmanlarını korur; düzenleme için harikadır ancak çoğu görüntüleyici ve web sitesi onu açamaz.`],
  [`macOS icon`, `macOS simgesi`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS, macOS'un simge biçimidir. ICO gibi tek bir görselin birkaç boyutunu, Retina ekranlar için 1024×1024'e kadar bir arada tutar ve Mac'te uygulama simgeleri için kullanılır.`],
  [`Camera RAW`, `Kamera RAW`],
  [`Windows only`, `Yalnızca Windows`],
  [`the photo of the Live Photo`, `Live Photo'nun fotoğrafı`],
  [`the video of the Live Photo`, `Live Photo'nun videosu`],

  // Vector graphics
  [`Vector graphics`, `Vektörel grafikler`],
  [`vector graphics`, `vektörel grafik`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, Windows meta dosyaları, Illustrator, EPS/PostScript ile CorelDRAW, Visio ve LibreOffice Draw çizimleri. SVG, CAD için DXF veya DWG'ye de dönüştürülebilir.`],
  [`SVG vector graphic`, `SVG vektörel grafiği`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG, XML tabanlı bir vektörel grafik biçimidir. Şekiller ve metin her boyutta net kalır; bu da onu web'deki logolar ve simgeler için ideal kılar, ancak birçok uygulama ve yükleme formu yalnızca piksel tabanlı görselleri kabul eder.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS, baskı ve tasarım işlerinden gelen bir vektörel biçimdir; matbaalara gönderilen logolar ve illüstrasyonlar için sık kullanılır. Çoğu modern uygulama, bir PostScript yorumlayıcısı olmadan onu gösteremez.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `PDF içeriğiyle kaydedilmiş AI dosyaları (Illustrator varsayılanı)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `PDF'leri görsellere, düzenlenebilir Word veya HWPX belgelerine, PowerPoint slaytlarına, metne veya çizgi roman arşivine dönüştürün; birleştirin, bölün, sıkıştırın veya sayfa seçin.`],
  [`PDF document`, `PDF belgesi`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF, her yerde aynı görünmesi gereken belgeleri paylaşmanın standardıdır. Yazı tipleri, düzen ve görseller sabittir ve her cihazda açılır. Bu da PDF'leri düzenlemeyi zorlaştırır.`],
  [`one page`, `tek sayfa`],

  // Documents
  [`Documents`, `Belgeler`],
  [`documents`, `belge`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Microsoft Office olmadan Word belgeleri, Çin OFD e-faturaları, isteğe bağlı LibreOffice motoruyla eski ve nadir kelime işlemci biçimleri ve kaydedilmiş e-postalar (EML ve Outlook MSG).`],
  [`Word document`, `Word belgesi`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX, Word 2007'den bu yana Microsoft Word'ün biçimidir (Office Open XML). Raporlar, mektuplar ve formlar gibi düzenlenebilir belgeler için en yaygın biçimdir.`],
  [`Word 97–2003 document`, `Word 97–2003 belgesi`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC, Word 97–2003'ün ikili biçimidir. Eski arşivler, resmî formlar ve eski sistemler hâlâ bu biçimi üretir, ancak yerini giderek DOCX'e bırakmaktadır.`],
  [`E-mail message`, `E-posta iletisi`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML, üst bilgileri, iletisi ve ekleriyle birlikte dosya olarak kaydedilmiş tek bir e-postadır (MIME biçimi). Outlook ve Thunderbird dahil çoğu e-posta uygulaması onu açabilir.`],
  [`Outlook message`, `Outlook iletisi`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG, Microsoft Outlook'tan bir e-postayı dışarı sürüklediğinizde Outlook'un kaydettiği dosyadır. Yalnızca Outlook açabildiği için Outlook olmayan bir bilgisayarda veya telefonda okumak zordur.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `Korece HWP/HWPX`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Hancom Office olmadan Korece Hancom Hangul belgeleri: HWP ↔ HWPX; PDF'ye, görsellere, Word'e, metne, Markdown'a ve HTML'ye; Word, Excel, PowerPoint, Markdown ve PDF'den HWPX'e.`],
  [`Hangul document (HWP)`, `Hangul belgesi (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP, Kore'de devlet dairelerinde, okullarda ve birçok şirkette standart kelime işlemci olan Hancom Office Hangul'un (한글) belge biçimidir. Kore dışında onu açabilen program azdır.`],
  [`Hangul document (HWPX)`, `Hangul belgesi (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX, Hancom Hangul'un açık, XML tabanlı biçimidir (OWPML, Kore ulusal standardı KS X 6101). Kore'deki kamu kurumları ikili HWP biçiminden bu biçime geçiyor.`],

  // Spreadsheets
  [`Spreadsheets`, `Elektronik tablolar`],
  [`spreadsheets`, `elektronik tablo`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Excel, OpenDocument ve CSV/TSV tabloları; Excel olmadan, Excel'e benzer sayfa sığdırmayla PDF'ye ya da birbirine.`],
  [`Excel workbook`, `Excel çalışma kitabı`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX, Excel 2007'den bu yana Microsoft Excel'in çalışma kitabı biçimidir. Tek bir çalışma kitabı formüller, biçimlendirme, grafikler ve görseller içeren birden fazla çalışma sayfası tutabilir.`],
  [`Excel 97–2003 workbook`, `Excel 97–2003 çalışma kitabı`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS, Excel 97–2003'ün ikili çalışma kitabı biçimidir. Birçok eski sistem ile banka ve muhasebe dışa aktarımları hâlâ bu biçimi üretir.`],
  [`Comma-separated values`, `Virgülle ayrılmış değerler`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV, her satırında bir tablo satırı bulunan düz metindir. Her elektronik tablo, veritabanı ve programlama dili onu okur, ancak biçimlendirme, formül veya birden fazla sayfa içermez.`],

  // Presentations
  [`Presentations`, `Sunumlar`],
  [`presentations`, `sunum`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint olmadan PowerPoint'ten PDF'ye, görsellere ve HWPX'e; isteğe bağlı LibreOffice motoruyla eski PPT, ODP ve Keynote.`],
  [`PowerPoint presentation`, `PowerPoint sunumu`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX, PowerPoint 2007'den bu yana Microsoft PowerPoint'in biçimidir. Metin, görseller, şekiller, tablolar, notlar ve animasyonlar içeren slaytlar tutar.`],
  [`PowerPoint 97–2003 presentation`, `PowerPoint 97–2003 sunumu`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT, PowerPoint 97–2003'ün ikili biçimidir. Eski ders slaytları ve arşivlenmiş sunumlar çoğu zaman hâlâ PPT biçimindedir.`],

  // Text & markup
  [`Text & markup`, `Metin ve işaretleme`],
  [`text and markup`, `metin ve işaretleme`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Düz metin, Markdown, HTML ve kaydedilmiş web sayfaları (MHTML) → PDF, Word, HWPX ve EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter ve diğer işaretleme dilleri, Markdown'ı PowerPoint slaytlarına da dönüştüren isteğe bağlı Pandoc motorunu kullanır.`],
  [`Plain text`, `Düz metin`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT, hiçbir biçimlendirme içermeyen düz metindir; en basit ve en taşınabilir belge biçimidir. Farklı olabilecek tek şey karakter kodlamasıdır (UTF-8, UTF-16 veya eski bir kod sayfası).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown hafif bir düz metin işaretleme dilidir: başlıklar için #, listeler için *, kalın yazı için **. Notlar, README dosyaları ve belgeler için popülerdir ve işlenmeden de okunabilir.`],
  [`Web page (HTML)`, `Web sayfası (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML, web sayfalarının dilidir. Kaydedilmiş bir .html dosyası her tarayıcıda açılır, ancak görünümü tarayıcıya ve bağlantılı stillerle görsellere bağlıdır; bunlar çevrimdışıyken eksik olabilir.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `LOG dosyaları ve betikler (PY, PAC, BAT, COMMAND) metin olarak okunur ve asla çalıştırılmaz`],
  [`the saved page, with its pictures`, `kaydedilmiş sayfa, görselleriyle birlikte`],

  // Data
  [`Data`, `Veri`],
  [`data files`, `veri dosyası`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML ve XML arasında dönüştürme; tablolar CSV ve Excel'e, CSV ve Excel'den. vCard kişileri CSV'ye ve CSV'den, eski telefonlardan gelenler dahil. Kurulacak bir şey yok.`],
  [`JSON data`, `JSON verisi`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON, web'in veri biçimidir: düz metin hâlinde nesneler, listeler, metinler ve sayılar. API'ler, uygulamalar ve ayar dosyaları onu her yerde kullanır.`],
  [`YAML data`, `YAML verisi`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML, JSON ile aynı türde veriyi parantez yerine girintiyle yazılmış olarak tutar. Docker, Kubernetes, CI hatları ve birçok uygulamanın yapılandırma dosyaları YAML'dir.`],
  [`vCard contacts`, `vCard kişileri`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf), kişiler için standart dosyadır. Telefonlar, Outlook, Google Kişiler ve iCloud adres defterlerini vCard olarak, çoğu zaman tek dosyada birçok kişiyle dışa aktarır.`],

  // E-books
  [`E-books & comics`, `E-kitaplar ve çizgi romanlar`],
  [`e-books and comics`, `e-kitap ve çizgi roman`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook ve çizgi roman arşivleri (CBZ, CBR, CB7…) → PDF, EPUB, Word ve daha fazlası; Kobo okuyucular için KEPUB. Yalnızca DRM'siz kitaplar.`],
  [`EPUB e-book`, `EPUB e-kitabı`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB, e-kitaplar için açık standarttır. Metin her ekrana sığacak şekilde yeniden akar; çoğu e-okuyucu ve okuma uygulaması onu destekler. Kindle, EPUB'u Send to Kindle aracılığıyla kabul eder.`],
  [`Kindle / Mobipocket e-book`, `Kindle / Mobipocket e-kitabı`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI, Amazon Kindle'ın yıllarca kullandığı eski Mobipocket e-kitap biçimidir. Eski e-kitap koleksiyonlarında hâlâ yaygındır, ancak Amazon AZW3/KFX ve EPUB'a geçmiştir.`],

  // Video
  [`Video`, `Video`],
  [`video`, `video`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Tüm yaygın video biçimleri → MP4 (H.264, HEVC veya AV1), WebM, MOV, MKV, AVI, GIF veya APNG; 720p seçeneği, grafik işlemcisinde donanım kodlama, MP3 veya M4A'ya ses çıkarma ve her kareyi görsel olarak kaydetme ile. İsteğe bağlı FFmpeg motorunu kullanır.`],
  [`MPEG-4 video`, `MPEG-4 videosu`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) en uyumlu video biçimidir. Genellikle H.264 veya H.265 video ve AAC sesle telefonlarda, TV'lerde, tarayıcılarda ve tüm video sitelerinde oynatılır.`],
  [`QuickTime movie`, `QuickTime filmi`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV, iPhone ve Mac'lerin kullandığı Apple QuickTime video biçimidir. Genellikle H.264 veya HEVC video içerir, ancak bazı düzenleyiciler, TV'ler ve web siteleri MP4'ü daha iyi işler.`],
  [`Matroska video`, `Matroska videosu`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska), çok sayıda video, ses ve altyazı izi tutabilen esnek, açık bir kapsayıcıdır. Filmler ve kayıtlar için popülerdir, ancak telefonlar, TV'ler ve düzenleyiciler onu her zaman oynatamaz.`],
  [`WebM video`, `WebM videosu`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM, tarayıcılar için geliştirilmiş açık bir video biçimidir (Vorbis veya Opus sesli VP8/VP9 ya da AV1 video). Ekran kayıtları ve indirmeler çoğu zaman WebM'dir, ancak birçok düzenleyici ve cihaz MP4 bekler.`],
  [`AVI video`, `AVI videosu`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI, Microsoft'un 1990'lardan kalma video kapsayıcısıdır. Video kameralar, eski fotoğraf makineleri ve arşivler hâlâ AVI dosyaları içerir; bu dosyalar çoğu zaman büyüktür ve telefonlarda zayıf desteklenir.`],
  [`one still frame or every frame`, `tek durağan kare veya her kare`],

  // Audio
  [`Audio`, `Ses`],
  [`audio`, `ses`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Müzikler, kayıtlar ve sesli notlar → MP3, M4A, WAV, FLAC, OGG, Opus, AAC veya kayıpsız WavPack ve TTA. APE, DSD ve DTS de okunur. İsteğe bağlı FFmpeg motorunu kullanır.`],
  [`MP3 audio`, `MP3 sesi`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3, klasik sıkıştırılmış ses biçimidir. Neredeyse her oynatıcı, araç ses sistemi ve telefon onu çalar; bu da onu müzik, podcast ve kayıt paylaşmak için en güvenli seçim yapar.`],
  [`MPEG-4 audio`, `MPEG-4 sesi`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A, iTunes, iPhone sesli notları ve birçok kayıt cihazının kullandığı, genellikle AAC içeren bir MPEG-4 ses dosyasıdır. Küçük boyutlarda iyi ses verir, ancak bazı oynatıcılar ve araç ses sistemleri yalnızca MP3 kabul eder.`],
  [`WAV audio`, `WAV sesi`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV, kayıt ve düzenleme için kullanılan sıkıştırılmamış sestir (genellikle PCM). Kaynağın birebir aynısı gibi duyulur, ancak CD kalitesinde dakikada yaklaşık 10 MB yer kaplar.`],
  [`FLAC lossless audio`, `FLAC kayıpsız sesi`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC kayıpsız sıkıştırılmış sestir: dosyaları hiç kalite kaybı olmadan WAV'ın yaklaşık yarısı boyutuna küçültür; bu da onu müzik arşivleri ve yüksek çözünürlüklü indirmeler için en sevilen biçim yapar.`],

  // Subtitles
  [`Subtitles`, `Altyazılar`],
  [`subtitles`, `altyazı`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML ve MicroDVD arasında motor gerekmeden dönüştürme, UTF-8 olarak kaydedilir; SSA ve SCC okunur. CP949 kodlamalı Korece SMI ve SRT dosyaları doğru okunur. Videodaki altyazılar FFmpeg ile çıkarılır.`],
  [`SubRip subtitles`, `SubRip altyazıları`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) en yaygın altyazı dosyasıdır: başlangıç ve bitiş zamanlarıyla numaralandırılmış satırlar ve düz metin. Neredeyse her oynatıcı, düzenleyici ve video sitesi onu kabul eder.`],
  [`Advanced SubStation Alpha subtitles`, `Advanced SubStation Alpha altyazıları`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha), anime fansub'larının ve Aegisub'ın kullandığı; yazı tipi, renk, konum ve efekt içeren biçimli altyazı biçimidir. Birçok cihaz ve site yalnızca düz SRT kabul eder.`],
  [`WebVTT subtitles`, `WebVTT altyazıları`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt), HTML5 videonun altyazı biçimidir. Web oynatıcıları, YouTube ve çevrimiçi eğitim platformları onu kullanır.`],
  [`SAMI subtitles (SMI)`, `SAMI altyazıları (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi), Microsoft'un HTML benzeri altyazı biçimidir. Kore'de hâlâ klasik altyazı dosyasıdır ve çoğu zaman yeni oynatıcıların bozuk karakterlerle gösterdiği eski CP949 kodlamasıyla kaydedilir.`],

  // Archives
  [`Archives`, `Arşivler`],
  [`archives`, `arşiv`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `ZIP, 7Z, RAR, TAR, disk görüntüleri ve daha birçok arşiv biçimini birlikte gelen 7-Zip motoruyla yeniden paketleyin veya açın ya da istediğiniz dosyaları tek bir ZIP'e paketleyin.`],
  [`ZIP archive`, `ZIP arşivi`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP evrensel arşiv biçimidir. Windows, macOS, telefonlar ve neredeyse her yükleme formu onu ek yazılım olmadan açar.`],
  [`7-Zip archive`, `7-Zip arşivi`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z, 7-Zip'in açık arşiv biçimidir. LZMA2 sıkıştırması genellikle ZIP'ten daha küçük dosyalar oluşturur, ancak her sistem veya web sitesi onu açamaz.`],
  [`RAR archive`, `RAR arşivi`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR, WinRAR'ın tescilli arşiv biçimidir ve parçalara bölünmüş indirmelerde yaygındır. Yeni Windows 11 sürümleri RAR'ı açabilir ama oluşturamaz; birçok araç da yalnızca ZIP kabul eder.`],
  [`Any files`, `Her türlü dosya`],

  // CAD
  [`CAD drawings`, `CAD çizimleri`],
  [`CAD drawings [in running text]`, `CAD çizimi`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `AutoCAD DWG ve DXF: AutoCAD olmadan birbirine ya da PDF, SVG ve PNG'ye dönüştürün.`],
  [`AutoCAD drawing`, `AutoCAD çizimi`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG, AutoCAD'in kendi çizim biçimi ve mimarlık ile mühendislikte en yaygın CAD dosyasıdır. AutoCAD veya bir DWG görüntüleyici olmadan açmak ya da paylaşmak zordur.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format), Autodesk'in CAD çizimleri için değişim biçimidir. Lazer kesiciler, CNC yazılımları ve çoğu CAD programı onu okur; bu yüzden çizimleri araçlar arasında taşımanın olağan yoludur.`],

  // 3D
  [`3D models`, `3B modeller`],
  [`3D models [in running text]`, `3B model`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF ve PLY arasında, FBX'ten de bunların herhangi birine dönüştürme; biçim destekliyorsa renkler, dokular ve malzemelerle birlikte; ayrıca gölgelendirilmiş bir PNG veya JPG görseline. Kurulacak bir şey yok.`],
  [`glTF binary (GLB)`, `glTF ikili (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB, web'in, AR'nin ve oyun motorlarının 3B biçimi olan glTF'nin tek dosyalık sürümüdür. Ağlar, malzemeler ve dokular tek ve kompakt bir dosyada paketlenir.`],
  [`STL 3D model`, `STL 3B modeli`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL, 3B baskının klasik dosyasıdır. Bir şeklin yalnızca üçgenlerini saklar, renk veya birim içermez; her dilimleyici ve CAD programı onu okur.`],
  [`Wavefront OBJ model`, `Wavefront OBJ modeli`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront), neredeyse her 3B programın açtığı düz metin bir 3B biçimidir. Malzemeler ve dokular yanında bir .mtl dosyası ve görseller olarak durur.`],

  // Fonts
  [`Fonts`, `Yazı tipleri`],
  [`fonts`, `yazı tipi`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Masaüstü ve web yazı tipleri: TTF, OTF, WOFF, WOFF2 ve EOT arasında dönüştürme.`],
  [`TrueType font`, `TrueType yazı tipi`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType), Windows ve macOS'ta en yaygın masaüstü yazı tipi biçimidir. Yazı tipini herhangi bir uygulamada kullanmak için kurmanız yeterlidir.`],
  [`OpenType font`, `OpenType yazı tipi`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType), Adobe ve Microsoft'un geliştirdiği bir yazı tipi biçimidir. PostScript (CFF) anahatlı OpenType yazı tipleri profesyonel yazı karakterlerinde yaygındır ve bitişik harfler gibi özellikleri destekler.`],
  [`Web font (WOFF2)`, `Web yazı tipi (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2, tüm modern tarayıcıların desteklediği sıkıştırılmış web yazı tipi biçimidir. Genellikle WOFF'tan yaklaşık %30 daha küçüktür; böylece sayfalar daha hızlı yüklenir.`],

  // Geospatial
  [`Geospatial data`, `Coğrafi veri`],
  [`geospatial data`, `coğrafi veri`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Haritalar ve GPS verileri: GeoJSON, KML, KMZ, GPX ve Shapefile arasında ve CSV, Excel ve JSON'a dönüştürme; koordinat içeren bir CSV'den de yeniden harita dosyasına. Yalnızca vektör verisi (noktalar, çizgiler ve alanlar), her zaman boylam ve enlem olarak kaydedilir. Kurulacak bir şey yok.`],
  [`one row per feature, with its coordinates`, `her coğrafi öğe için koordinatlarıyla bir satır`],
  [`a CSV with longitude and latitude columns or WKT`, `boylam ve enlem sütunları veya WKT içeren bir CSV`],

  // Camera RAW
  [`Camera RAW photo`, `Kamera RAW fotoğrafı`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Kamera RAW dosyaları (CR2, CR3, NEF, ARW, DNG, RAF, ORF ve daha fazlası) bir fotoğrafın işlenmemiş sensör verisini tutar. Düzenleme için en fazla ayrıntıyı korurlar, ancak büyüktürler ve görüntülemek için özel yazılım gerekir.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `Bir web sitesi, eski bir Windows uygulaması ya da iPhone'u olmayan biri fotoğraflarınıza ihtiyaç duyduğunda JPG güvenli seçimdir. Bir grup HEIC fotoğrafın tamamı tek seferde dönüştürülür ve her JPG kendi özgün dosyasının yanına kaydedilir.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Fotoğrafı bir tur daha JPG sıkıştırması eklemeden düzenlemeye devam etmek istiyorsanız PNG'yi seçin. PNG kayıpsızdır; dosyaların özgün HEIC dosyasından birkaç kat büyük olmasını bekleyin.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC, iPhone'ların fotoğraf kaydettiği gibi, bir fotoğrafı aynı kalitede bir JPG'nin yaklaşık yarısı kadar yerde tutar. HEIC kaydetmek için ücretsiz FFmpeg motoru gerekir (yaklaşık 100 MB, uygulamada bir kez indirilir). EXIF, renk profili ve yön bilgisi korunur.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Web sitelerinden kaydedilen görseller çoğu zaman WebP'dir. PNG'ye dönüştürmek tam kaliteyi ve varsa saydamlığı korur; sonuç her düzenleyicide, slayt destesinde ve belgede çalışır.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Görsel bir fotoğrafsa ve dosya boyutu önemliyse, örneğin WebP'yi reddeden yükleme formları için, JPG'yi seçin.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `PNG olarak kaydedilen ekran görüntüleri ve dışa aktarılan fotoğraflar megabaytlarca yer tutabilir. Fotoğraflar JPG olarak genellikle çok küçülür; metin ağırlıklı ekran görüntüleri ve logolar için ise PNG çoğu zaman daha iyi biçim olarak kalır.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `JPG'yi PNG'ye dönüştürmek JPG sıkıştırmasıyla kaybolan ayrıntıyı geri getirmez, ancak kaybın sürmesini durdurur: sonraki her düzenleme ve kayıt kayıpsız olur. Bir görseli rötuşlamadan veya bir düzenleyicide saydamlık eklemeden önce dönüştürün.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Modern web sitelerinden ve telefonlardan gelen AVIF görseller birçok eski programda, görüntüleyicide ve yükleme formunda açılmaz. JPG ise biraz daha büyük dosyalar pahasına her yerde açılır.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP web siteleri için idealdir: fotoğraflar JPG'den çok daha küçük olur, grafikler saydamlıklarını korur. WEBP ön ayarı, web için iyi bir denge olan 85 kalitesiyle kaydeder.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Taranmış sayfaların, fişlerin ve belge fotoğraflarının çoğu zaman tek bir PDF olarak gönderilmesi gerekir. Tek bir PDF için görselleri PDF birleştir ön ayarına, her görsel için ayrı bir PDF için PDF'nin üzerine bırakın. Varsayılan olarak her sayfa kendi görselinin boyutunu alır.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Tek bir ICO, Windows'un masaüstü, Dosya Gezgini ve görev çubuğu simgeleri için ihtiyaç duyduğu her şeyi karşılar ve web sitesi favicon'u olarak da çalışır. En net sonuç için en az 256×256 px boyutunda kare bir PNG ile başlayın.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Windows'ta Mac uygulama simgesi yapmak genellikle ek araçlar gerektirir; Filee bir PNG'yi doğrudan ICNS dosyasına dönüştürür. Retina boyutları net kalsın diye 1024×1024 px kare bir PNG kullanın.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Bir Photoshop tasarımını Photoshop'u olmayan kişilerle paylaşın: PNG görseli kaydedildiği hâliyle, görünür katmanlar birleştirilmiş ve saydamlık korunmuş olarak gösterir. PNG katman saklayamaz; düzenleme için PSD'yi saklayın.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee; Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One ve daha fazlasının RAW dosyalarını okur ve varsayılan ayarlarla banyo eder. Bir çekimden paylaşılabilir JPG'ler almanın hızlı yoludur; yaratıcı düzenleme için önce bir RAW düzenleyici kullanın.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Bir hafıza kartı dolusu CR2 dosyasını tek seferde bırakın: Filee onları paralel olarak dönüştürür ve her JPG'yi kendi RAW dosyasının yanına kaydeder. Yeni Canon fotoğraf makineleri CR3 yazar; Filee onu da okur.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `NEF dosyaları olduğu gibi göndermek için fazla büyük ve fazla alışılmadıktır. JPG olarak küçük ve her yerde görüntülenebilen fotoğraflara dönüşürler; mesajlaşma uygulamaları için JPG 70% veya Yarı boyut ön ayarını kullanın. Nikon'un Coolpix fotoğraf makinelerinden gelen NRW dosyaları da aynı şekilde çalışır.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Birçok uygulama, slayt destesi ve yükleme formu SVG kabul etmez. Filee vektörel çizimi saydamlığı olan bir PNG'ye işler; sıkıştırılmış SVGZ dosyaları da çalışır.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `SVG'den PDF'ye dönüştürmede sonuç vektörel kalır: çizgiler ve metin her yakınlaştırmada ve baskıda net kalır, dosya da küçük olur. Logoları ve diyagramları matbaaya göndermek veya belgelere eklemek için kullanışlıdır.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS yalnızca bir PostScript yorumlayıcısıyla görüntülenebilir; Filee bunun için Ghostscript kullanır. PDF vektörel çizimi korur; böylece her yerde açılır ve yine net basılır. PostScript (.ps) dosyaları da aynı şekilde çalışır.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Her sayfa ayrı bir JPG olur; 10 sayfalık bir PDF size 10 görsel verir. Görsel kabul eden ama PDF kabul etmeyen sohbetler, slaytlar ve sosyal medya gönderileri için kullanışlıdır.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG metni ve çizgileri JPG bozulmaları olmadan keskin tutar; bu da slaytlara, diyagramlara, notalara ve üzerine not almak ya da bir sunuma eklemek istediğiniz sayfalara uygundur.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee PDF'yi sayfa görselleri yerine gerçek paragraflar içeren bir Word belgesine dönüştürür; böylece yazım hatalarını düzeltebilir veya metni yeniden kullanabilirsiniz. Karmaşık düzenler rötuş gerektirebilir; yalnızca sayfa görselleri içeren taranmış bir PDF'de çıkarılacak metin yoktur.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee kendiliğinden PDF → Word → EPUB yolunu izler; böylece metin bir telefonun veya e-okuyucunun ekranına sığacak şekilde yeniden akar. En iyi sonucu gerçek metin içeren PDF'lerde verir. Başlıklar düz paragraf olarak gelir ve taranmış sayfalarda dönüştürülecek metin yoktur.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee PDF'nin metnini bir Word belgesine aktarır, onu HWPX olarak yazar ve ardından HWP olarak kaydeder; bunların hepsini yerleşik motorlarla yapar. Gerçek metin içeren PDF'lerde çalışır. Karmaşık düzenler rötuş gerektirebilir; taranmış sayfalarda çıkarılacak metin yoktur.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee PDF'yi önce bir Word belgesine, ardından Markdown'a dönüştürür; paragrafları, başlıkları ve kalın metni ayırt edebildiği yerlerde korur. Notlar, wikiler veya metni başka araçlara yapıştırmak için kullanışlıdır. Taranmış sayfalarda dönüştürülecek metin yoktur.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Kore'deki kurumlar belgeleri çoğu zaman Hangul biçiminde ister. Filee PDF'nin metnini, dönüştürme için Hancom Office gerekmeden, Hancom Hangul'da açıp düzenleyebileceğiniz bir HWPX dosyasına dönüştürür; bir form eski biçimi istiyorsa ardından HWP'ye dönüştürün.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Bir PDF'nin PowerPoint'te gösterilmesi veya mevcut bir sunuma eklenmesi gerektiğinde kullanışlıdır: her sayfa PDF'nin birebir aynısı gibi görünen bir slayt olur ve sayfanın metni konuşmacı notlarında bekler. Slaytlar görsel olduğu için metni değiştirmek istiyorsanız PDF'yi bunun yerine DOCX'e dönüştürün.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Microsoft Word veya LibreOffice gerekmez: Filee DOCX'i kendisi okur ve sayfaları üst ve alt bilgiler, tablolar ve görsellerle düzenler. Birkaç belgeyi tek bir PDF'de birleştirmek için onları PDF birleştir ön ayarına bırakın.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Arşivlerden, resmî formlardan veya eski sistemlerden gelen Word 97–2003 belgeleri her yerde açılan PDF'lere dönüşür. Aynı motor ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord ve Apple Pages dosyalarını da dönüştürür.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Kayıtlar, faturalar veya hukuki dosyalar için e-postaları PDF olarak kaydedin: PDF gönderen, alıcılar, tarih, konu ve iletiyi gösterir ve e-posta uygulaması olmadan her yerde açılır.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee HWP sayfalarını açık kaynaklı bir Hangul motoru olan rhwp ile işler; Hancom Office de onun izin penceresi de devreye girmez. Korece belgeleri HWP açamayan kişilere göndermek için kullanışlıdır.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Bir Hangul belgesini yurt dışındaki iş arkadaşlarınızın düzenleyebileceği bir Word dosyasına dönüştürün. Metin, paragraflar ve tablolar aktarılır; çok sayıda serbest konumlu nesne içeren düzenleri Word'de kısaca kontrol etmekte fayda var.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `Yeni, XML tabanlı Hangul biçimi HWPX de HWP gibi dönüştürülür: sayfaları tamamen çevrimdışı olarak yerleşik rhwp motoru düzenler. Kamu kurumlarının HWPX formlarını PDF olarak arşivlemek için kullanışlıdır.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Bazı sistemler ve yeni iş akışları yalnızca HWPX kabul eder. Filee ikili HWP'yi Hancom Office olmadan rhwp ile HWPX'e dönüştürür ve bir grup eski belgenin tamamını tek seferde dönüştürür.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Hangul'un eski sürümleri ve bazı başvuru portalları hâlâ .hwp bekler. Filee HWPX'i rhwp ile yeniden HWP'ye dönüştürür; böylece her dosyayı Hangul'da açıp yeniden kaydetmeniz gerekmez.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Filee'nin kendi HWPX yazıcısı Word düzenini aktarır: sayfa boyutu ve kenar boşlukları, sayfa numaralı üst ve alt bilgiler, birleştirilmiş hücreli, kenarlıklı ve gölgelendirilmiş tablolar, metin kutuları, şekiller ve görseller. Yazdığı her dosya testlerde üç bağımsız HWPX okuyucuyla denetlenir.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Hâlâ .hwp isteyen kurumlar ve formlar için. Filee Word belgesini kendi yazıcısıyla HWPX olarak yazar ve bunu rhwp ile HWP'ye dönüştürür; ikisi de yerleşiktir, bu yüzden dönüştürme için Hancom Office gerekmez.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Word belgesinin her sayfası bir JPG olur (Filee belgeyi önce bir PDF olarak düzenler); bir sayfayı internette paylaşmak veya hızlı bir önizleme göndermek için kullanışlıdır. Word gerekmez.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Her görünür çalışma sayfası; sayı biçimleri, yazı tipleri, dolgular, kenarlıklar ve birleştirilmiş hücreleriyle Excel'in gösterdiği gibi ayrı bir bölüm olur. Geniş sayfalar, Excel'in "Tüm Sütunları Bir Sayfaya Sığdır" seçeneğindeki gibi sayfa genişliğine ölçeklenir ve dondurulmuş başlık satırları her sayfada tekrarlanır.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV tek bir tablo tutar; bu yüzden Filee her çalışma sayfası için bir CSV yazar. Hücreler değer olarak dışa aktarılır; veritabanları, betikler ve içe aktarma formları için hazırdır.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Bir XLSX çalışma kitabı, CSV'nin tutamadığı biçimlendirmeyi, formülleri ve ek çalışma sayfalarını tutabilir. Tüm CSV dışa aktarımlarınızı seçip tek seferde bırakın; Excel'in içe aktarma penceresi olmadan her dosya için bir çalışma kitabı elde edin.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Eski Excel 97–2003 çalışma kitaplarını Excel veya LibreOffice olmadan yükseltin: dönüştürme yerleşiktir. XLSX dosyaları genellikle daha küçüktür, makro taşıyamaz ve güncel her elektronik tablo uygulamasında açılır.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Her slayt, slayt boyutunda bir PDF sayfası olur; metin, şekiller, görseller, tablolar ve asıl slayt tasarımı korunur. Sunumları dağıtmak veya PowerPoint dosyalarının kabul edilmediği yerlere yüklemek için kullanışlıdır. Animasyonlar ve konuşmacı notları PDF'ye dahil edilmez.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Eski PowerPoint 97–2003 sunumları herkesin açabileceği, yazdırabileceği veya yükleyebileceği PDF'lere dönüşür. Keynote (.key), ODP ve WPS (DPS) sunumları da aynı şekilde dönüştürülür.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Her slayt bir JPG olur; sosyal medya gönderileri, küçük resimler, sohbet iletileri veya bir video düzenleyici için hazırdır. Slaytlarda çok sayıda küçük metin varsa bunun yerine PNG'yi seçin.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Başlıklar, listeler (görev listeleri dahil), tablolar, kod, alıntılar, bağlantılar, görseller, dipnotlar ve matematik ifadeleri Pandoc, LaTeX veya tarayıcı olmadan A4 sayfalara yerleştirilir. Notları ve README dosyalarını Markdown okumayan kişilerle paylaşmanın hızlı bir yolu.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Yerleşik, Pandoc gerekmez. Başlıklar, listeler, tablolar, bağlantılar ve dipnotlar aktarılır; böylece belgeyi Word'de düzenlemeye ve yeniden biçimlendirmeye devam edebilirsiniz.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Düz metin, her satırı bir paragraf olan temiz bir A4 PDF'ye dönüşür. Filee UTF-8 ve UTF-16'nın yanı sıra eski Korece (CP949) metin dosyalarını da tanır; böylece eski günlükler ve notlar bozuk karakterlere dönüşmez.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Bir web sayfasını veya HTML raporunu her yerde aynı görünen, arşivlenebilen veya yazdırılabilen bir PDF olarak kaydedin. Filee bilgisayarınıza kaydedilmiş .html dosyalarını dönüştürür ve birkaçını tek bir PDF'de birleştirebilir.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `PDF sabit bir sayfa düzeni korur; bu da bir e-kitabı yazdırmak, bilgisayarda okumak veya EPUB okuyucusu olmayan bir cihaza göndermek için kullanışlıdır.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Eski bir Kindle/Mobipocket kitaplığını EPUB'a taşıyın; böylece Apple Books, Google Play Kitaplar, Kobo ve çoğu okuma uygulamasında açılır. Bu yön yerleşiktir, bu yüzden Calibre gerekmez.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `MOBI ve AZW3 dosyalarını e-kitap aracı Calibre yazar. Güncel Kindle'lar Send to Kindle aracılığıyla EPUB'u da kabul ettiği için MOBI özellikle eski Kindle cihazları ve uygulamaları için kullanışlıdır.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Bir dersin, konserin veya röportajın sesini her yerde çalan bir MP3 olarak kaydedin: arabada, eski bir oynatıcıda veya bir deşifre aracında.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `iPhone ve Mac videoları MOV dosyalarıdır. MP4 olarak Android telefonlarda, akıllı TV'lerde, eski Windows uygulamalarında ve MOV'u reddeden yükleme formlarında oynatılırlar. Video ve ses genellikle MP4'e olduğu gibi sığar; bu yüzden Filee yalnızca kapsayıcıyı değiştirir: kalite kaybı olmaz, HDR korunur, işlem saniyeler sürer. MP4 720p ön ayarı 4K klipleri paylaşım için küçültür.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Örneğin OBS'den gelen MKV kayıtları çoğu zaman video düzenleyicilere aktarılamaz veya TV'lerde oynatılamaz; MP4 ise neredeyse her yerde kabul edilir. Dönüştürme yerel olarak çalışır; uzun kayıtların asla yüklenmesi gerekmez.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Ekran kayıtları ve tarayıcıdan kaydedilen videolar çoğu zaman WebM'dir; birçok video düzenleyici, eski oynatıcı ve mesajlaşma uygulaması bu biçimi iyi işlemez. MP4 neredeyse her yerde oynatılır ve bir grup klibin tamamı tek seferde dönüştürülür.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Kısa bir klibi sohbetler, belgeler veya hata raporları için animasyonlu bir GIF'e dönüştürün. Kısa tutun: GIF her kareyi 256 renkli bir görsel olarak saklar; uzun veya yüksek çözünürlüklü videolar çok büyük dosyalar oluşturur.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `JPG üzerine bırakılan bir video tek bir durağan görsel verir. Küçük resim seçmek veya bir klibi kare kare incelemek için Kareleri çıkar (JPG) ön ayarını kullanın: görseller videonun yanındaki bir klasöre, her kare veya her N'inci kare olarak kaydedilir. 100.000'den fazla görsel verecek veya diski dolduracak bir video daha başlamadan reddedilir.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Eski video kameralardan ve fotoğraf makinelerinden gelen AVI dosyaları büyüktür ve çoğu zaman telefonların ve TV'lerin artık oynatmadığı codec'ler kullanır. Modern sıkıştırmalı bir MP4 genellikle çok daha küçüktür ve her yerde oynatılır.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Bir WAV kaydı dakikada yaklaşık 10 MB yer kaplar; MP3 olarak bunun küçük bir kısmı yeter ve yine her cihazda çalar.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Kayıpsız FLAC arşivinizi evde tutun; MP3 kopyalarını telefona, araba için bir USB belleğe veya FLAC çalmayan eski bir oynatıcıya koyun. Albümlerin tamamı tek seferde dönüştürülür.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `iPhone sesli notları, DRM'siz iTunes indirmeleri ve birçok kayıt cihazı M4A üretir. MP3 ise her oynatıcı, araç ses sistemi ve yükleme formu tarafından kabul edilir.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `RAR arşivlerini yalnızca ZIP kabul eden kişiler, yükleme formları ve sistemler için ZIP olarak yeniden paketleyin. Ne RAR'ı okumak ne de ZIP'i yazmak için WinRAR gerekir.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z çoğu zaman daha iyi sıkıştırır, ancak ZIP ek yazılım olmadan her bilgisayarda ve telefonda açılır. 7-Zip'i olmayan birine arşiv gönderirken dönüştürün.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Çizimleri AutoCAD'i olmayan müşterilere, şantiye ekiplerine veya matbaalara gönderin: PDF her bilgisayarda ve telefonda açılır. Birkaç çizim tek bir PDF'de birleştirilebilir.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `CAD programlarından, lazer kesim işlerinden veya tasarım alışverişlerinden gelen DXF dosyaları herkesin açıp yazdırabileceği PDF'lere dönüşür. Örneğin web önizlemeleri için SVG ve PNG de kullanılabilir.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF; lazer kesicilerin, CNC yazılımlarının ve çoğu CAD programının okuduğu değişim biçimidir. DWG'yi DXF'ye dönüştürmek AutoCAD çizimlerini bu araçlarda açmanızı sağlar; DXF'den DWG'ye dönüştürme de çalışır.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Bir yazı tipini kendi web sitenizde barındırın: WOFF2, her modern tarayıcının desteklediği, genellikle WOFF'tan yaklaşık %30 daha küçük sıkıştırılmış web yazı tipi biçimidir. Yazı tipinin lisansının web'e gömmeye izin verdiğinden emin olun.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Bazı eski programlar, kesim ve nakış makineleri ile oyun motorları yalnızca TrueType yazı tiplerini kabul eder. Bir OTF yazı tipi ailesinin tamamını yazı tipi düzenleyici olmadan tek seferde TTF'ye dönüştürün.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Logolar, imzalar ve taramalar için Çizgileri SVG'ye dönüştür ön ayarını kullanın: mürekkep, saydam arka plan üzerinde tek bir siyah şekle dönüşür. SVG'ye vektörleştir ise simgeler ve illüstrasyonlar için en fazla 64 rengi korur. Fotoğraflar düz renk lekeleri olarak çıkar; bu yüzden vektörleştirme en çok çizimlere uygundur.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Bir logonun JPG'si veya taranmış bir eskiz, her boyutta net kalan ve kesim plotteri, web sitesi ya da matbaa için hazır bir SVG'ye dönüşür. JPG gürültüsü küçük lekelere dönüşür; sonuç kalabalık görünüyorsa ön ayardaki Ayrıntı ayarını düşürün.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Lazer kesiciler, CNC yazılımları ve CAD programları DXF okur. Filee SVG'nin dış hatlarını milimetre cinsinden yazar; 100 mm genişliğindeki bir şekil 100 mm kalır. Eğriler ince çoklu çizgilere dönüşür. Dolgular, görseller ve filtreler çıkarılır.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Outlook'tan dışarı sürüklenen e-postalar yalnızca Outlook'un açabildiği MSG dosyalarıdır. PDF olarak gönderen, alıcılar, tarih, konu ve iletiyi korur ve her yerde açılır. Outlook gerekmez.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML elle okumak ve düzenlemek için daha kolaydır; yapılandırma dosyalarının onu kullanmasının nedeni budur. Anahtarlar sıralarını korur; geri okunduğunda sayı veya true/false olarak algılanacak metinler tırnak içine alınır.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Bir yapılandırma dosyasını bir API, bir betik veya yalnızca JSON okuyan bir araç için JSON'a dönüştürün. Çapalar ve takma adlar çözümlenir; birden fazla belge içeren bir dosya tek bir diziye dönüşür. JSON'da yorum olmadığı için yorumlar çıkarılır.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Kayıtlardan oluşan bir JSON listesi Excel'de açabileceğiniz bir tabloya dönüşür: her kayıt için bir satır, her anahtar için bir sütun. {"users": […]} gibi bir sarmalayıcının içine bakılır. Tablo olmayan veriler bozuk bir dosya yerine bir iletiyle durdurulur.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Bir adres defterini Excel'e veya bir toplu e-posta aracına aktarın: her kişi için ad, kuruluş, e-posta, telefon, adres ve doğum günü içeren bir satır. CP949 kodlamalı eski Kore telefonlarından gelen kişiler doğru okunur.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Web oynatıcıları ve çevrimiçi eğitim platformları WebVTT ister. Zamanlama, satır sonları ve italikler aktarılır; motor gerekmez.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Birçok oynatıcı, TV ve düzenleyici SMI okumaz; eski Korece SMI dosyaları da çoğu zaman bozuk karakterlerle görünür. Filee CP949'u algılar, en çok satırı olan dili seçer ve temiz bir UTF-8 SRT kaydeder.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Bir TV, telefon veya video sitesi biçimli ASS altyazılarını reddettiğinde düz SRT çalışır. Kalın, italik, altı çizili ve renkler korunur; konumlar, yazı tipleri ve efektler çıkarılır.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Bir filmin altyazılarını düzenlemek veya çevirmek için çıkarın. İlk metin altyazı izi SRT olarak kaydedilir; görüntü tabanlı altyazılar (DVD, Blu-ray) metne dönüştürülemez. Ücretsiz FFmpeg motoru gerekir.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Bir baskı dosyasını OBJ'yi tercih eden bir 3B programda açın. STL'de birim olmadığı için Filee onu milimetre olarak okur ve OBJ'yi de milimetre cinsinden, çoğu 3B programda olduğu gibi Y ekseni yukarıyı gösterecek şekilde yazar.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `3B yazıcı dilimleyicileri STL kullanır. Her şekildeki yüzler üçgenlere bölünür ve Y-yukarı, Z-yukarı olur; böylece dik bir model baskı tablasında ayakta durur. STL yalnızca şekli tuttuğu için renkler ve dokular OBJ'de kalır.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Web'den veya bir oyun motorundan gelen bir modeli OBJ okuyan bir programa aktarın. .mtl dosyası ve dokular .obj dosyasının yanına yazılır; bunları birlikte tutun.`],

  // FAQ
  [`Is Filee really free?`, `Filee gerçekten ücretsiz mi?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Evet. Filee MIT lisansıyla ücretsiz ve açık kaynaklıdır: reklam, filigran, hesap ve deneme süresi yoktur; kendi koyduğu bir dosya sayısı veya dosya boyutu sınırı da yoktur.`],
  [`Does it work offline? Are my files uploaded?`, `Çevrimdışı çalışır mı? Dosyalarım yüklenir mi?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Her dönüştürme kendi bilgisayarınızda çalışır ve dosyalar asla yüklenmez. İnternet yalnızca isteğe bağlı bir motoru indirmek veya güncellemeleri denetlemek için kullanılır; gizli belgeler, fotoğraflar ve kayıtlar bilgisayarınızda kalır.`],
  [`Which file formats does Filee support?`, `Filee hangi dosya biçimlerini destekler?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee {categoryCount} kategoride {formatTotal} dosya biçimini okur: {categoryList}. Bunların {builtinTotal} tanesi kurulumdan hemen sonra çalışır; diğerleri ücretsiz, isteğe bağlı bir motor kullanır. Biçim kataloğu her biçimi ve nelere dönüştürülebildiğini listeler.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Microsoft Office, Hancom Office veya LibreOffice gerekli mi?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF. Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Hayır. Word, Excel ve PowerPoint dosyaları (DOCX, XLSX, XLS, CSV, PPTX) ile Korece HWP/HWPX belgeleri Filee'nin yerleşik motorlarıyla dönüştürülür. Filee, Office veya Hancom Office kurulu olsa bile onları kullanmaz; LibreOffice yalnızca DOC, PPT, ODT ve RTF gibi eski biçimler için uygulama içinden indirilebilen isteğe bağlı bir motordur. Şekillendirme gerektiren metin (Arapça, İbranice, Hint yazıları, Tayca ve diğerleri) bir istisnadır: böyle metin içeren DOCX, TXT, Markdown, HTML, XLSX, PPTX ve HWPX dosyaları isteğe bağlı LibreOffice motoruyla PDF'ye ve görsellere dönüştürülür. LibreOffice yoksa dosya, bozuk bir PDF'ye dönüşmek yerine yazı sisteminin adını belirten bir mesajla başarısız olur.`],
  [`What are the optional engines?`, `İsteğe bağlı motorlar nelerdir?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Büyük motorlar kurulum dosyasında yer almaz. Onları kurulumun motor sayfasında işaretleyin ya da ihtiyaç duyduğunuzda Filee içinden indirin: {engineDetails}. Filee'nin kendi klasörüne kaydedilirler ve istediğiniz zaman kaldırılabilirler; uygulama sürümlerini, indirme hızını ve kalan süreyi gösterir. FFmpeg, calibre, Pandoc, Ghostscript veya LibreOffice bilgisayarınızda zaten varsa (Scoop dahil PATH'te veya Program Files'ta) Filee onu kullanır ve indirmeyi atlar; bu kopya test edildiği sürümden eskiyse bunu belirtir. Belirli bir kopyayı Ayarlar → Dönüştürme motorları → Kendi kopyamı kullan ile seçebilirsiniz.`],
  [`Does installing Filee need administrator rights?`, `Filee'yi kurmak yönetici hakları gerektirir mi?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Yalnızca bir kez, kurulum sırasında. Kurulum Filee'yi tüm kullanıcılar için Program Files'a yerleştirir ve Windows 11'de “Filee ile dönüştür” öğesini Dosya Gezgini menüsünün en üstüne ekler. Ardından Filee normal kullanıcı hesabınızla çalışır. Sessiz kurulum için kurulum dosyasını /VERYSILENT /SUPPRESSMSGBOXES ile çalıştırın. Program kuramıyorsanız taşınabilir ZIP'i kullanın: istediğiniz bir yere açın ve Filee.exe'yi çalıştırın.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `Filee Windows 10'da açılmıyor: pencere yok, hata yok. Ne yapabilirim?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Bu durum, uzun süredir güncellenmemiş bir Windows 10'da, işlemcisi donanım destekli yığın korumasını (Hardware-enforced Stack Protection, CET) destekleyen bir bilgisayarda yaşanır. Windows bu korumayı açar ancak .NET'in ihtiyaç duyduğu bir parça eksiktir; bu yüzden Filee ve kurulum dosyası pencere veya ileti göstermeden hemen kapanır. Mevcut Windows güncelleştirmelerini (en son toplu güncelleştirme) yüklemek sorunu giderir. Güncelleme mümkün değilse korumayı yalnızca Filee için kapatmak genellikle işe yarar: yönetici olarak açtığınız PowerShell'de Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack komutunu çalıştırın, ardından aynısını filee-cli.exe ve kurulum dosyasının adı için yapın (ya da taşınabilir ZIP'i kullanın). Geri almak için bu girdileri Windows Güvenliği → Uygulama ve tarayıcı denetimi → Açıktan yararlanma koruması ayarları → Program ayarları bölümünden kaldırın.`],
  [`Can I convert many files at once?`, `Birden fazla dosyayı aynı anda dönüştürebilir miyim?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Evet. İstediğiniz kadar dosya seçip tek seferde bırakın: Filee onları paralel olarak dönüştürür, başarısız bir dosya diğerlerini asla durdurmaz ve ön ayarlar her şeyi tek bir PDF'de birleştirebilir ya da tek bir ZIP'e paketleyebilir.`],
  [`Can I convert from the Windows 11 right-click menu?`, `Windows 11 sağ tık menüsünden dönüştürebilir miyim?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Evet. Dosya Gezgini'nde dosyalara sağ tıklayın ve “Filee ile dönüştür” seçeneğini seçin. Windows 11'de bu öğeyi “Daha fazla seçenek göster” adımına gerek kalmadan ana menüye de koyabilirsiniz: Ayarlar → Genel bölümünde bir kez “Ana menüye ekle” düğmesine tıklayın ve yönetici izni isteğini onaylayın. Gönder menüsü, bir klavye kısayolu ve ana penceredeki bırakma alanı da çalışır.`],
  [`Can Filee convert from the command line or automatically?`,
    `Filee komut satırından veya otomatik olarak dönüştürebilir mi?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Evet. Kurulum filee komutunu PATH'e ekleyebilir: filee convert *.heic --to jpg dosyaları, joker karakterleri ve klasörleri ön ayarlarınızla dönüştürür, betikler için JSON yazdırır ve çıkış kodları döndürür. İzlenen klasörler bir klasöre gelen dosyaları otomatik olarak dönüştürür ve özgün dosyaları kenara taşıyabilir. Bunları uygulamadaki İzlenen klasörler sayfasından ya da bir terminalde filee watch ile kurun.`],
  [`How do I convert a file, for example HEIC to JPG?`, `Bir dosyayı, örneğin HEIC'i JPG'ye nasıl dönüştürürüm?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Dosya Gezgini'nde dosyaları seçin, Ctrl tuşunu (veya seçtiğiniz tuşu) basılı tutun ve sürükleyin. İmlecin yanında biçimlerden oluşan bir halka açılır: dosyaları JPG üzerine bırakın, yeni dosyalar özgün dosyaların yanında belirir. En yaygın dönüştürmeler için adım adım rehberler de var.`],
  [`Why use Filee instead of an online converter?`, `Neden çevrimiçi bir dönüştürücü yerine Filee?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Çevrimiçi dönüştürücüler dosyalarınızı başkasının sunucusuna yükler, çoğu zaman dosya boyutunu ve sayısını sınırlar ve hızlı bir bağlantıya bağlıdır. Filee bilgisayarınızda dönüştürür: özel dosyalar özel kalır, büyük videolar ve yüzlerce dosya sorun olmaz; internet olmadan, ücretsiz ve reklamsız çalışır.`],
  [`Which operating systems are supported?`, `Hangi işletim sistemleri destekleniyor?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 ve 11 (64 bit) ile Linux (x64 ve ARM64, Ubuntu 22.04 veya üstü) tam sürümlerdir. Linux'ta sürükleme hareketi bir X11 oturumu gerektirir; Wayland ile KDE Plasma'da deneyseldir, diğer Wayland masaüstlerinde ise bırakma alanı ve dosya yöneticisinin sağ tık menüsü çalışır. macOS 13 veya üstü (Apple silicon ve Intel) önizlemedir: uygulama henüz Apple'ın noter onayından (notarization) geçmediği için macOS, Gizlilik ve Güvenlik bölümünde bir kez izin vermenizi ister. İndirme bölümünde sisteminizi seçin.`],
]);
